import { both, phrase, replies, type PhoneLessonContract, type PhoneMemoryScope } from './contracts';

type Entry = {
  name: string; role: string; gender: 'male' | 'female'; student: string;
  incoming: boolean; situation: string; goals: string[]; done: string;
  facts: string[]; ask: string[]; avoid: string[];
  hello: [string, string, string]; scope?: PhoneMemoryScope; turns?: 3 | 4;
};

// The actor owns facts; ask contains only information belonging to the student.
// Student examples are authored separately below and never enter actor instructions.
function call(e: Entry): PhoneLessonContract {
  return {
    callerName: e.name, callerNameRu: e.name, callerRole: e.role,
    callerGender: e.gender, userRole: e.student,
    callType: e.incoming ? 'incoming' : 'outgoing', situationSummary: e.situation,
    callerObjective: `В роли «${e.role}» помочь собеседнику выполнить задачу: ${e.goals.join('; ')}.`,
    studentObjective: e.goals.join('; '), goals: e.goals, completionCondition: e.done,
    facts: e.facts, studentDetails: e.ask,
    forbiddenActions: [
      'Говорить от лица ученика или задавать ему вопросы о фактах, которыми владеет персонаж.',
      'Выдавать предложение за согласие ученика; назначать встречу или оформлять заказ без подтверждения.',
      'Утверждать, что видишь ученика, его вещи или документы через обычный телефонный звонок.',
      ...e.avoid,
    ],
    memoryScope: e.scope ?? 'general', targetTurns: e.turns ?? 4,
    greeting: both(phrase(...e.hello)), studentReplies: replies(),
  };
}

